def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter
    counts = Counter(v for row in grid for v in row)
    bg = counts.most_common(1)[0][0]

    seen = set()
    comps = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == bg or (r, c) in seen:
                continue
            color = grid[r][c]
            stack = [(r, c)]
            seen.add((r, c))
            cells = set()
            while stack:
                x, y = stack.pop()
                cells.add((x, y))
                for nx, ny in ((x-1,y),(x+1,y),(x,y-1),(x,y+1)):
                    if (0 <= nx < h and 0 <= ny < w and
                        (nx, ny) not in seen and grid[nx][ny] == color):
                        seen.add((nx, ny))
                        stack.append((nx, ny))
            comps.append((color, cells))

    # Find the prominent L-shaped object and its corner/arm directions.
    choices = []
    for color, cells in comps:
        junctions = []
        for r, c in cells:
            dirs = []
            for dr, dc in ((-1,0),(1,0),(0,-1),(0,1)):
                if (r+dr, c+dc) in cells:
                    dirs.append((dr, dc))
            vertical = [d for d in dirs if d[1] == 0]
            horizontal = [d for d in dirs if d[0] == 0]
            if vertical and horizontal:
                for vd in vertical:
                    for hd in horizontal:
                        junctions.append((r, c, vd[0], hd[1]))
        if junctions:
            # Prefer L components with long arms and substantial extent.
            rs = [r for r, c in cells]
            cs = [c for r, c in cells]
            score = (max(rs)-min(rs) + 1) + (max(cs)-min(cs) + 1)
            choices.append((score, color, cells, junctions))

    if not choices:
        return [row[:] for row in grid]

    _, marker_color, marker_cells, junctions = max(choices, key=lambda x: x[0])
    r0, c0, dr, dc = junctions[0]

    targets = []
    for color, cells in comps:
        if cells == marker_cells:
            continue
        cr = sum(r for r, c in cells) / len(cells)
        cc = sum(c for r, c in cells) / len(cells)
        if (cr-r0) * dr < 0 and (cc-c0) * dc < 0:
            targets.append((len(cells), color, cells))

    if targets:
        target = max(targets, key=lambda x: x[0])[2]
    else:
        # In some layouts the marked object points toward an L-shaped region
        # rather than the diagonally opposite quadrant.
        by_color = Counter()
        for color, cells in comps:
            if cells != marker_cells:
                by_color[color] += len(cells)
        if not by_color:
            return [row[:] for row in grid]
        target_color = by_color.most_common(1)[0][0]
        target = max((cells for color, cells in comps
                      if color == target_color), key=len)

    out = [row[:] for row in grid]
    for r, c in target:
        out[r][c] = marker_color
    return out
